#!/bin/bash

# Script to auto-generate Claude context from project state
# Run this before starting work with Claude to get latest context

set -e

OUTPUT_FILE=".claude/context_auto.md"

cat > "$OUTPUT_FILE" << 'EOF'
# Auto-Generated Context

**Generated**: $(date)
**Branch**: $(git branch --show-current)
**Last Commit**: $(git log -1 --oneline)

---

## Recent Git Activity

### Last 10 Commits
```
$(git log --oneline -10)
```

### Files Changed (Last 24 hours)
```
$(git diff --name-only HEAD@{1.day.ago} HEAD 2>/dev/null || echo "No changes in last 24 hours")
```

### Current Git Status
```
$(git status --short)
```

### Unstaged/Uncommitted Changes
$(if git diff --quiet && git diff --cached --quiet; then
    echo "✓ No uncommitted changes"
else
    echo "⚠️ You have uncommitted changes:"
    echo '```'
    git diff --stat
    git diff --cached --stat
    echo '```'
fi)

---

## Project Structure Overview

### Key Directories
```
$(tree -L 2 -d -I '__pycache__|*.pyc|venv|.venv|node_modules|.git|staticfiles|htmlcov|.pytest_cache|.ruff_cache' --dirsfirst | head -50)
```

### OCPI22 Module Structure
```
$(tree -L 3 -d ocpi22/ -I '__pycache__|*.pyc|migrations|locale|locales' --dirsfirst)
```

---

## Test Coverage Summary

$(if command -v pytest &> /dev/null; then
    echo "### Running Coverage Report..."
    echo '```'
    pytest --co -q 2>/dev/null | tail -20 || echo "Unable to generate test collection"
    echo '```'
else
    echo "pytest not found - skipping coverage"
fi)

---

